import math
from fractions import Fraction as F
from functools import reduce
def rising(v,n): return math.prod(v+i for i in range(n))
def cvec(g,a): return [math.comb(g,j)*(-1)**(g-j)*rising(a,g-j)*rising(4-a,j) for j in range(g+1)]
def pvec(g,a,m):
 c=cvec(g,a); return [m*c[0]]+[(m+j)*c[j]+(m+j-1-g)*c[j-1] for j in range(1,g+1)]+[m*c[g]]
def col(g,a,m):
 d=1-g-(a+m); s=-a-g if d>0 else -a-g+abs(d); sg=1 if d>0 else -1
 return {s+j:sg*x for j,x in enumerate(pvec(g,a,m)) if x}
def comp(g,k,q):
 cen=1-g; return [col(g,a,m) for a in range(0,2*k+1,2) for m in (cen-q-a,cen+q-a)]
def defect(g,a,q):
 c=cvec(g,a); J=[c[0]]+[c[j]+c[j-1] for j in range(1,g+1)]+[c[g]]; out={}
 for s,sg in [(-a-g,-2),(-a-g+q+2,2)]:
  for j,x in enumerate(J): out[s+j]=out.get(s+j,0)+sg*x
 return {r:x for r,x in out.items() if x}
def solve(M,y):
 A=[[F(x) for x in row]+[F(v)] for row,v in zip(M,y)]; m=len(A); n=len(A[0])-1; piv=[]; r=0
 for c in range(n):
  p=next((i for i in range(r,m) if A[i][c]),None)
  if p is None: continue
  A[r],A[p]=A[p],A[r]; z=A[r][c]; A[r]=[x/z for x in A[r]]
  for i in range(m):
   if i!=r and A[i][c]:
    z=A[i][c]; A[i]=[A[i][j]-z*A[r][j] for j in range(n+1)]
  piv.append(c); r+=1
 for i in range(r,m):
  if all(A[i][j]==0 for j in range(n)) and A[i][n]: return None
 x=[F(0) for _ in range(n)]
 for i,c in enumerate(piv): x[c]=A[i][n]
 return x
def cert(g,k,q,a):
 cols=comp(g,k,q+2); b=defect(g,a,q); rows=sorted(set(b)|{r for c in cols for r in c})
 M=[[c.get(r,0) for r in rows] for c in cols]+[[b.get(r,0) for r in rows]]
 lam=solve(M,[0]*len(cols)+[1])
 den=math.lcm(*[x.denominator for x in lam]); ints=[int(x*den) for x in lam]; gg=reduce(math.gcd,[abs(x) for x in ints if x] or [1]); ints=[x//gg for x in ints]
 return [(r,x) for r,x in zip(rows,ints) if x]
for k in range(2,9):
 z=cert(2,k,1,0); print('k',k,'support',len(z),'range',(z[0][0],z[-1][0]),'vec',z[:12],('...' if len(z)>12 else ''))
